[tikz]\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\coordinate (A) at (0,0);\coordinate (B) at (3,1.732);\coordinate (C) at (3,0);
\draw[->] (A)--(0,2.5) node[above]{N};\draw[->] (B)--(3,2.7) node[above]{N};
\draw (A)--(B) node[pos=0.72,above left]{$5\text{ km}$};\draw[dashed] (A)--(C) node[midway,below]{$x$};\draw[dashed] (C)--(B);
\draw (2.8,0)--(2.8,0.2)--(3,0.2);
\draw (0,0.8) arc (90:30:0.8);\node at (0.55,1.05){$60^{\circ}$};
\draw (0.6,0) arc (0:30:0.6);\node at (1.05,0.22){$30^{\circ}$};
\node[below left] at (A){$A$};\node[right] at (B){$B$};
\end{tikzpicture}[/tikz]
The angle from east is $90^{\circ}-60^{\circ}=30^{\circ}$. The eastward distance is adjacent to this angle.
$\begin{align*}\cos30^{\circ}&=\frac{x}{5}\\x&=5\cos30^{\circ}\\x&\approx4.33\text{ km}\end{align*}$

[tikz]\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\coordinate (A) at (0,0);\coordinate (B) at (1.268,-2.719);\coordinate (C) at (1.268,0);
\draw[->] (A)--(0,1.5) node[above]{N};\draw[->] (B)--(1.268,1) node[above]{N};
\draw (A)--(B) node[pos=0.75,left]{$8\text{ km}$};\draw[dashed] (A)--(C);\draw[->] (B)--(C) node[midway,right]{$x$};\draw[dashed] (A)--(0,-1.65) node[left]{S};
\draw (1.068,0)--(1.068,-0.2)--(1.268,-0.2);
\draw (0,0.65) arc (90:-65:0.65);\node at (1,0.4){$155^{\circ}$};
\draw (0,-0.9) arc (270:295:0.9);\node at (0.72,-1.15){$25^{\circ}$};
\node[left] at (A){$A$};\node[below] at (B){$B$};\node[right] at (C){$C$};
\end{tikzpicture}[/tikz]
The angle from south is $180^{\circ}-155^{\circ}=25^{\circ}$. The return north equals the first journey's southward distance.
$\begin{align*}\cos25^{\circ}&=\frac{x}{8}\\x&=8\cos25^{\circ}\\x&\approx7.25\text{ km}\end{align*}$

[tikz]\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\coordinate (O) at (0,0);\coordinate (P) at (1.5,-2.598);\coordinate (Q) at (2.5,-2.598);\coordinate (C) at (0,-2.598);
\draw[->] (O)--(0,1.4) node[above]{N};\draw[->] (P)--(1.5,-1.4) node[above]{N};\draw[->] (Q)--(2.5,-1.4) node[above]{N};
\draw (O)--(P) node[pos=0.72,right]{$9\text{ km}$};\draw[->] (P)--(Q) node[midway,below]{$2\text{ km}$};\draw[dashed] (O)--(C);\draw[dashed] (C)--(P) node[midway,below]{$x$};
\draw (0,-2.398)--(0.2,-2.398)--(0.2,-2.598);
\draw (0,-0.8) arc (270:300:0.8);\node at (0.4,-1.15){$30^{\circ}$};
\node[left] at (O){$O$};\node at (1.35,-3.25){$P$};\node[right] at (Q){$Q$};
\end{tikzpicture}[/tikz]
The first journey makes an angle of $180^{\circ}-150^{\circ}=30^{\circ}$ with south.
$\begin{align*}\sin30^{\circ}&=\frac{x}{9}\\x&=9\sin30^{\circ}\\x&=4.5\text{ km}\end{align*}$
Add the second journey's eastward distance.
$\begin{align*}\text{Total east}&=4.5+2\\&=6.5\text{ km}\end{align*}$

[tikz]\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\coordinate (O) at (0,0);\coordinate (P) at (1.35,1.609);\coordinate (Q) at (3.495,-0.191);
\draw[->] (O)--(0,2.5) node[above]{N};\draw[->] (P)--(1.35,3.1) node[above]{N};\draw[->] (Q)--(3.495,0.9) node[above]{N};
\draw (O)--(P);\node[anchor=east] at (-0.45,1.65){$6\text{ km}$};\draw (P)--(Q) node[midway,above right]{$8\text{ km}$};\draw (O)--(Q) node[midway,below]{$d$};
\draw (1.196,1.425)--(1.38,1.271)--(1.534,1.455);
\draw (0,0.7) arc (90:50:0.7);\node at (0.35,1.05){$40^{\circ}$};
\draw (1.35,2.259) arc (90:-40:0.65);\node at (2.25,1.95){$130^{\circ}$};
\draw (0.386,0.46) arc (50:-3.13:0.6);\node at (0.85,0.35){$\theta$};
\node[below left] at (O){$O$};\node[above left] at (P){$P$};\node[right] at (Q){$Q$};
\end{tikzpicture}[/tikz]
The bearing of $O$ from $P$ is $040^{\circ}+180^{\circ}=220^{\circ}$. Thus $\angle OPQ=220^{\circ}-130^{\circ}=90^{\circ}$.
(a)
$\begin{align*}d^2&=6^2+8^2\\d^2&=100\\d&=10\text{ km}\end{align*}$
(b)
$\begin{align*}\tan\theta&=\frac{8}{6}\\\theta&=\tan^{-1}\left(\frac{8}{6}\right)\\\theta&=53.130\ldots^{\circ}\end{align*}$
The direction to $Q$ is clockwise from $OP$.
$\begin{align*}\text{Bearing}&=40^{\circ}+53.130\ldots^{\circ}\\&\approx093^{\circ}\text{T}\end{align*}$

[tikz]\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\coordinate (O) at (0,0);\coordinate (P) at (0,2.25);\coordinate (Q) at (3,2.25);
\draw[->] (O)--(0,3.3) node[above]{N};\draw[->] (Q)--(3,3.3) node[above]{N};
\draw (O)--(P) node[midway,left]{$9\text{ km}$};\draw (P)--(Q) node[midway,above]{$12\text{ km}$};\draw (O)--(Q);
\draw (0,2.05)--(0.2,2.05)--(0.2,2.25);
\draw (0,0.65) arc (90:36.87:0.65);\node at (0.55,0.95){$\theta$};
\node[below] at (O){$O$};\node[left] at (P){$P$};\node[right] at (Q){$Q$};
\end{tikzpicture}[/tikz]
(a) The angle at $O$ is measured clockwise from north.
$\begin{align*}\tan\theta&=\frac{12}{9}\\\theta&=\tan^{-1}\left(\frac{12}{9}\right)\\\theta&=53.130\ldots^{\circ}\end{align*}$
The bearing of $Q$ from $O$ is $053^{\circ}\text{T}$.
(b) The opposite direction differs by $180^{\circ}$. Use the unrounded angle.
$\begin{align*}\text{Return bearing}&=53.130\ldots^{\circ}+180^{\circ}\\&\approx233^{\circ}\text{T}\end{align*}$

[tikz]\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\coordinate (T) at (0,0);\coordinate (D) at (-0.884,0.884);\coordinate (C) at (-3.005,-1.237);
\draw[->] (T)--(0,1.8) node[above]{N};\draw[->] (D)--(-0.884,2.4) node[above]{N};\draw[->] (C)--(-3.005,-0.2) node[above]{N};
\draw (T)--(D) node[midway,above right]{$5\text{ km}$};\draw (D)--(C);\draw (T)--(C) node[midway,below right]{$13\text{ km}$};
\draw (-0.728,0.728)--(-0.884,0.572)--(-1.04,0.728);
\draw (0,0.55) arc (90:-225:0.55);\node at (0.8,-0.65){$315^{\circ}$};
\draw (-0.884,1.384) arc (90:-135:0.5);\node at (-1.75,1.5){$225^{\circ}$};
\draw (-0.247,0.247) arc (135:202.38:0.35);\node at (-0.6,0.2){$\theta$};
\node[right] at (T){$T$};\node[above left] at (D){$D$};\node[below left] at (C){$C$};
\end{tikzpicture}[/tikz]
The bearing of $T$ from $D$ is $315^{\circ}-180^{\circ}=135^{\circ}$. Thus $\angle TDC=225^{\circ}-135^{\circ}=90^{\circ}$.
$\begin{align*}\cos\theta&=\frac{5}{13}\\\theta&=\cos^{-1}\left(\frac{5}{13}\right)\\\theta&=67.380\ldots^{\circ}\end{align*}$
The turn from $TD$ to $TC$ is anticlockwise.
$\begin{align*}\text{Bearing}&=315^{\circ}-67.380\ldots^{\circ}\\&\approx248^{\circ}\text{T}\end{align*}$

[tikz]\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\coordinate (H) at (0,0);\coordinate (A) at (1.5,2.598);\coordinate (B) at (1.949,-1.125);
\draw[->] (H)--(0,3.2) node[above]{N};\draw[->] (A)--(1.5,3.8) node[above]{N};\draw[->] (B)--(1.949,0.1) node[above]{N};
\draw (H)--(A) node[midway,above left]{$24\text{ km}$};\draw (H)--(B) node[midway,below left]{$18\text{ km}$};\draw (A)--(B) node[midway,right]{$d$};
\draw (0.12,0.208)--(0.328,0.088)--(0.208,-0.12);
\draw (0,0.8) arc (90:60:0.8);\node at (0.3,1.15){$30^{\circ}$};
\draw (0,0.6) arc (90:-30:0.6);\node at (0.95,0.6){$120^{\circ}$};
\node[left] at (H){$H$};\node[right] at (A){$A$};\node[below] at (B){$B$};
\end{tikzpicture}[/tikz]
In $3$ hours the ships travel $8\times3=24$ km and $6\times3=18$ km. Their bearings differ by $120^{\circ}-30^{\circ}=90^{\circ}$, so $\angle AHB=90^{\circ}$.
$\begin{align*}d^2&=24^2+18^2\\d^2&=900\\d&=30\text{ km}\end{align*}$
